deleted = 0

    AND title LIKE CONCAT('%', #{query.title}, '%')


    AND status = #{query.status}


    AND price >= #{query.minAmount}


    AND price <= #{query.maxAmount}


    AND create_time >= CONCAT(#{query.startDate}, ' 00:00:00')


    AND create_time <= CONCAT(#{query.endDate}, ' 23:59:59')


    AND publisher_id = #{publisherId}


    AND (status = 3 OR publisher_id = #{publisherId})


    AND status = 3
    AND publisher_id != #{publisherId}
    AND NOT EXISTS (
        SELECT 1
        FROM trade_order o
        WHERE o.post_id = trade_post.id
          AND o.status IN (0, 1, 2)
    )
